using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
namespace LWS.TruckSports.Editor {public static class SportsPortraitAuthoring {
 public static void Create(){const string path="Assets/TruckSports/Resources/Broadcast truck portrait.png";if(File.Exists(path)){AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var existing=(TextureImporter)AssetImporter.GetAtPath(path);if(existing.spriteImportMode!=SpriteImportMode.Single){existing.spriteImportMode=SpriteImportMode.Single;existing.SaveAndReimport();}return;}Directory.CreateDirectory(Path.GetDirectoryName(path));var source=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/NWH/Vehicle Physics 2/Vehicles/Euro Truck by GR3D/SemiTruck.prefab");if(source==null)throw new Exception("Owned NWH truck portrait source required");var preview=new PreviewRenderUtility();var root=new GameObject("Actual installed truck broadcast portrait");var materials=new List<Material>();Texture2D image=null;try{foreach(var f in source.GetComponentsInChildren<MeshFilter>(true)){if(f.sharedMesh==null)continue;var original=f.GetComponent<MeshRenderer>();if(original==null)continue;var g=new GameObject(f.name);g.transform.SetParent(root.transform);g.transform.SetPositionAndRotation(f.transform.position,f.transform.rotation);g.transform.localScale=f.transform.lossyScale;g.AddComponent<MeshFilter>().sharedMesh=f.sharedMesh;var renderer=g.AddComponent<MeshRenderer>();renderer.sharedMaterials=original.sharedMaterials;if(f.name=="Cab"){renderer.sharedMaterials=original.sharedMaterials.Select(m=>{var copy=new Material(m);if(copy.HasProperty("_BaseColor"))copy.SetColor("_BaseColor",Color.white);if(copy.HasProperty("_Color"))copy.SetColor("_Color",Color.white);materials.Add(copy);return copy;}).ToArray();}}preview.AddSingleGO(root);var bounds=new Bounds(root.GetComponentsInChildren<Renderer>()[0].bounds.center,Vector3.zero);foreach(var r in root.GetComponentsInChildren<Renderer>())bounds.Encapsulate(r.bounds);var camera=preview.camera;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.025f,.035f,.065f,1);camera.orthographic=true;camera.orthographicSize=Mathf.Max(bounds.extents.y,bounds.extents.z)*1.12f;camera.nearClipPlane=.1f;camera.farClipPlane=100;camera.transform.position=bounds.center+new Vector3(9,5,12);camera.transform.LookAt(bounds.center);preview.lights[0].intensity=1.4f;preview.lights[0].transform.rotation=Quaternion.Euler(40,30,0);preview.lights[1].intensity=1;preview.lights[1].transform.rotation=Quaternion.Euler(340,220,0);preview.BeginStaticPreview(new Rect(0,0,160,160));preview.Render(true);image=preview.EndStaticPreview();File.WriteAllBytes(path,image.EncodeToPNG());}finally{preview.Cleanup();foreach(var m in materials)UnityEngine.Object.DestroyImmediate(m);if(image!=null)UnityEngine.Object.DestroyImmediate(image);if(root!=null)UnityEngine.Object.DestroyImmediate(root);}AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var importer=(TextureImporter)AssetImporter.GetAtPath(path);importer.textureType=TextureImporterType.Sprite;importer.spriteImportMode=SpriteImportMode.Single;importer.alphaIsTransparency=true;importer.maxTextureSize=256;importer.SaveAndReimport();}
}}
